function facingRow82(facing){
  let f=(facing||'down').toLowerCase();
  if(f==='up'||f==='back') return 1;
  if(f==='left') return 2;
  if(f==='right') return 3;
  return 0
}
function classifyHumanoidSprite82(n={}, player=false){
  let blob=((n.name||'')+' '+(n.role||'')+' '+(n.species||'')+' '+(n.career||'')+' '+(S.species||'')+' '+(S.career||'')+' '+(S.spec||'')).toLowerCase();
  if(player) blob=((S.name||'')+' '+(S.species||'')+' '+(S.career||'')+' '+(S.spec||'')).toLowerCase();
  if(/protocol|c-?3po/.test(blob)) return 'protocol_droid';
  if(/astromech|r2|droid pilot/.test(blob)) return 'astromech_droid';
  if(/mechanic|tech|engineer|slicer/.test(blob)) return 'mechanic_tech';
  if(/wookie|wookiee/.test(blob)) return 'wookie_bruiser';
  if(/twi|twi'lek|twilek/.test(blob)) return 'twilek_scoundrel';
  if(/rodian/.test(blob)) return 'rodian_hunter';
  if(/mon cal|moncal|mon calamari/.test(blob)) return 'moncal_officer';
  if(/force|jedi|sith|adept|mystic|consular|guardian|seer|nightsister/.test(blob)) return 'force_adept';
  if(/bounty|mandalor|hunter|merc|assassin|tracker/.test(blob)) return 'bounty_hunter';
  if(/imperial|storm|trooper|navy|security/.test(blob)) return 'imperial_soldier';
  if(/rebel|alliance|freedom/.test(blob)) return 'rebel_trooper';
  if(/droid/.test(blob)) return 'astromech_droid';
  return 'human_smuggler'
}
function drawCharSprite82(ctx,key,facing,x,y,w,h,frame=1){
  let img=ART82.images.characters; if(!img || !img.complete) return false;
  let idx=ART82.charKeys.indexOf(key); if(idx<0) idx=0;
  let col=idx%4,row=Math.floor(idx/4), f=Math.max(0,Math.min(2,frame|0));
  let cx=col*ART82.charCellW + ART82.charCentersX[f], cy=row*ART82.charCellH + ART82.charCentersY[facingRow82(facing)];
  let sx=cx-ART82.charCropW/2, sy=cy-ART82.charCropH/2;
  ctx.imageSmoothingEnabled=false;
  ctx.drawImage(img,sx,sy,ART82.charCropW,ART82.charCropH,x-w/2,y-h,w,h);
  return true
}
function chooseCreatureKey82(name=''){
  let t=(name||'').toLowerCase();
  if(/wampa/.test(t)) return 'wampa';
  if(/nexu/.test(t)) return 'nexu';
  if(/acklay/.test(t)) return 'acklay';
  if(/reek/.test(t)) return 'reek';
  if(/blurrg/.test(t)) return 'blurrg';
  if(/massiff/.test(t)) return 'massiff';
  if(/mynock/.test(t)) return 'mynock';
  if(/dianoga/.test(t)) return 'dianoga';
  if(/varactyl/.test(t)) return 'varactyl';
  if(/bogwing|dragon/.test(t)) return 'bogwing';
  if(/lava|flea/.test(t)) return 'lava_flea';
  if(/rathtar/.test(t)) return 'rathtar';
  if(/gundark/.test(t)) return 'gundark';
  if(/vornskr|hound|tracker beast/.test(t)) return 'vornskr';
  if(/krayt|worm/.test(t)) return 'krayt_hatchling';
  if(/sarlacc|tentacle/.test(t)) return 'sarlacc_spawn';
  if(/orray|rhino|horn/.test(t)) return 'orray';
  if(/tooka|cat/.test(t)) return 'tooka';
  if(/raptor/.test(t)) return 'nysillin_raptor';
  if(/bantha/.test(t)) return 'bantha_calf';
  if(/tick|spider/.test(t)) return 'stone_tick';
  if(/womp|rat/.test(t)) return 'womp_rat_pack';
  if(/scavenger|scrap droid|salvage droid/.test(t)) return 'droid_scavenger_beast';
  if(/force|horror|apparition/.test(t)) return 'force_vergence_horror';
  if(/beast|creature|shaoryn/.test(t)) return 'gundark';
  if(/droid/.test(t)) return 'droid_scavenger_beast';
  return 'massiff'
}
function drawCreature82(ctx,key,x,y,w,h,selected=false){
  let img=ART82.images.creatures; if(!img || !img.complete) return false;
  let idx=ART82.creatureKeys.indexOf(key); if(idx<0) idx=0;
  let col=idx%6,row=Math.floor(idx/6), crop=ART82.creatureCrop;
  let sx=col*ART82.creatureCellW+crop[0], sy=row*ART82.creatureCellH+crop[1], sw=crop[2], sh=crop[3];
  ctx.imageSmoothingEnabled=false;
  ctx.drawImage(img,sx,sy,sw,sh,x-w/2,y-h/2,w,h);
  if(selected){ctx.strokeStyle='#ffe36b';ctx.lineWidth=2;ctx.strokeRect(x-w/2-4,y-h/2-4,w+8,h+8)}
  return true
}
function renderArtPreviews82(){
  let cv=$('artPreviewChar82'); if(cv){ let c=cv.getContext('2d'); c.fillStyle='#08111a'; c.fillRect(0,0,cv.width,cv.height); drawCharSprite82(c,'bounty_hunter','front',cv.width/2,76,48,70,1); }
  cv=$('artPreviewCreature82'); if(cv){ let c=cv.getContext('2d'); c.fillStyle='#08111a'; c.fillRect(0,0,cv.width,cv.height); drawCreature82(c,'acklay',cv.width/2,55,96,72,false); }
  cv=$('artPreviewCantina82'); if(cv){ let c=cv.getContext('2d'), img=ART82.images.cantina; c.fillStyle='#08111a'; c.fillRect(0,0,cv.width,cv.height); if(img && img.complete) c.drawImage(img,0,0,img.width,img.height,0,0,cv.width,cv.height); }
}
function renderArtShowcase82(){
  ensureArt82();
  let host=$('guide'); if(!host || $('artGallery82')) return;
  let box=document.createElement('section');
  box.id='artGallery82'; box.className='artGallery82';
  box.innerHTML=`<div class="row"><div><h3>Sprite & Art Direction Integration</h3><div class="small">These are now the live visual targets and atlases for Sable Reach. The build below integrates the character sprite sheet, creature bestiary sheet, and cantina environment art into the actual UI renderers.</div></div><span class="tag">PHASE 81–82</span></div>
  <div class="artGrid82">
    <div class="artCard82"><img src="${ART82_URIS.characters}" alt="Character sprite sheet"><div class="small"><b>Character Atlas</b><br>Used for the player, NPCs, crew portraits, and retro combat allies.</div></div>
    <div class="artCard82"><img src="${ART82_URIS.creatures}" alt="Creature sprite sheet"><div class="small"><b>Creature Atlas</b><br>Used for enemy combat art and visual style grounding for creature encounters.</div></div>
    <div class="artCard82"><img src="${ART82_URIS.cantina}" alt="Cantina environment art"><div class="small"><b>Cantina Environment</b><br>Used as the current interior style target for scenes, crew ambience, and future room-map work.</div></div>
  </div>
  <div class="artPreviewStrip82">
    <div class="artMini82"><canvas id="artPreviewChar82" width="140" height="110"></canvas><div class="small"><b>Sprite Preview:</b> Friendly unit</div></div>
    <div class="artMini82"><canvas id="artPreviewCreature82" width="140" height="110"></canvas><div class="small"><b>Sprite Preview:</b> Creature enemy</div></div>
    <div class="artMini82"><canvas id="artPreviewCantina82" width="140" height="110"></canvas><div class="small"><b>Sprite Preview:</b> Interior atmosphere</div></div>
  </div>
  <div class="spriteNotice82">This is the first integration pass. The game now actually draws from the supplied sprite sheets in the pixel world, crew portraits, and retro combat scenes. The next pass can go even deeper with full tile-map conversion and more room-specific art.</div>`;
  host.insertAdjacentElement('afterend', box);
  renderArtPreviews82();
}
function enhanceCrewScene82(){
  let el=$('crewScene72'); if(!el) return;
  el.classList.add('cantinaEnhanced82');
  if(!$('cantinaHero82')){
    let d=document.createElement('div'); d.id='cantinaHero82'; d.className='cantinaHero82';
    d.innerHTML=`<div class="row"><b>Cantina / Interior Style Target</b><span class="tag">ART</span></div><div class="cantinaFrame82"><img src="${ART82_URIS.cantina}" alt="Cantina pixel-art scene"></div><div class="small" style="margin-top:7px">Crew and social scenes are now grounded on this warmer cantina / room style reference.</div>`;
    el.prepend(d);
  }
}
const _p82pxDrawHumanoid67=pxDrawHumanoid67;
pxDrawHumanoid67=function(ctx,sx,sy,n,player=false,facing='down'){
  ensureArt82();
  let key=classifyHumanoidSprite82(n,player);
  let frame=Math.floor(Date.now()/220)%3;
  if(drawCharSprite82(ctx,key,facing,sx+8,sy+15,18,22,frame)) {
    if(player){ ctx.strokeStyle='#ffe36b'; ctx.lineWidth=1; ctx.strokeRect(sx+2,sy+1,12,14); }
    return;
  }
  return _p82pxDrawHumanoid67(ctx,sx,sy,n,player,facing)
}
const _p82drawPortrait69=drawPortrait69;
drawPortrait69=function(canvas,n,expression='neutral'){
  ensureArt82();
  if(!canvas) return;
  let key=classifyHumanoidSprite82(n,false), img=ART82.images.characters;
  if(img && img.complete){
    let ctx=canvas.getContext('2d'); canvas.width=64; canvas.height=64; ctx.imageSmoothingEnabled=false;
    ctx.fillStyle='#05090d'; ctx.fillRect(0,0,64,64); ctx.fillStyle='#0e1822'; ctx.fillRect(3,3,58,58); ctx.fillStyle='#172535'; ctx.fillRect(5,5,54,54);
    for(let i=0;i<9;i++){ let x=((i+3)*7)%54+5, y=((i+5)*11)%52+6; ctx.fillStyle=i%2?'#334b60':'#70899b'; ctx.fillRect(x,y,1,1); }
    drawCharSprite82(ctx,key,'front',32,51,42,56,1);
    if(expression==='pleased'){ ctx.strokeStyle='#d4ad50'; ctx.strokeRect(6,6,52,52); }
    return;
  }
  return _p82drawPortrait69(canvas,n,expression)
}
