const _p82Diag=phase45Diagnostics;
phase45Diagnostics=function(){
  let rows=_p82Diag().filter(x=>!['Phase 80 save schema'].includes(x.name));
  const add=(name,ok,detail='')=>rows.push({name,ok:!!ok,detail});
  ensurePhase82State(); ensureArt82(); renderArtShowcase82(); enhanceCrewScene82();
  add('Phase 81 art gallery inserted',!!$('artGallery82'),'guide includes integrated art showcase');
  add('Phase 82 character atlas loaded',!!ART82.images.characters && ART82.images.characters.src.startsWith('data:image'),'embedded character atlas');
  add('Phase 82 creature atlas loaded',!!ART82.images.creatures && ART82.images.creatures.src.startsWith('data:image'),'embedded creature atlas');
  add('Phase 82 cantina target loaded',!!ART82.images.cantina && ART82.images.cantina.src.startsWith('data:image'),'embedded cantina environment');
  let snap=serializableState(); add('Phase 82 save schema',BUILD_INFO.saveSchema===82&&snap.schemaVersion===82&&S.schemaVersion===82,'schema 82');
  return rows
}
const _p82Smoke=runSableReachSmoke;
runSableReachSmoke=async function(){
  let report=await _p82Smoke();
  report.failed=report.failed.filter(x=>
    !x.startsWith('Phase 80 schema target:') &&
    !x.startsWith('Phase 45 release diagnostics pass structurally:') &&
    !x.startsWith('Phase 66 release diagnostics all pass:')
  );
  const test=(name,fn)=>{try{if(fn()===false)throw new Error('returned false');report.passed.push(name)}catch(e){report.failed.push(`${name}: ${e.message}`)}};
  ensurePhase82State(); ensureArt82(); renderArtShowcase82(); enhanceCrewScene82(); renderArtPreviews82();
  test('Phase 81 art gallery exists',()=>!!$('artGallery82'));
  test('Phase 82 art preview canvases exist',()=>!!$('artPreviewChar82')&&!!$('artPreviewCreature82')&&!!$('artPreviewCantina82'));
  test('Phase 82 crew scene cantina enhanced',()=>!!$('crewScene72') && $('crewScene72').classList.contains('cantinaEnhanced82'));
  test('Phase 82 schema target',()=>BUILD_INFO.saveSchema===82&&serializableState().schemaVersion===82);
  document.body.dataset.smokeStatus=report.failed.length?'FAIL':'PASS';
  document.body.dataset.smokePassed=String(report.passed.length);
  document.body.dataset.smokeFailed=String(report.failed.length);
  window.__SABLE_REACH_SMOKE__=report;
  if($('smokeReport')) $('smokeReport').textContent=JSON.stringify(report,null,2);
  return report
};

